//! Stage 1 golden tests: data loading parity and thermodynamics against the tables generated by
//! the Python reference (`rust/golden/generate_stage1_golden.py`).

use amcrax_engine::data::DataRoot;
use amcrax_engine::verify::{Golden, stage1};
use std::path::PathBuf;

fn repo() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../..")
}

fn golden() -> Golden {
    Golden::open(&repo().join("rust/golden/stage1")).expect("stage 1 golden tables")
}

#[cfg(feature = "yaml")]
#[test]
fn data_loading_parity() {
    let r = stage1::data(&DataRoot::new(repo()), &golden()).expect("data check runs");
    print!("{}", r.render());
    assert!(r.passed(), "data loading parity failed");
}

#[test]
fn thermodynamics_golden() {
    let r = stage1::thermo(&golden()).expect("thermo check runs");
    print!("{}", r.render());
    assert!(r.passed(), "thermodynamics golden comparison failed");
}

#[test]
fn embedded_data_equal_repository_files() {
    let root = DataRoot::new(repo());
    let n = root.read(amcrax_engine::thermo::nasa7::DATA_FILE).unwrap();
    assert_eq!(n.sha256, amcrax_engine::thermo::Nasa7::embedded().sha256);
    let c = root
        .read(amcrax_engine::thermo::peng_robinson::DATA_FILE)
        .unwrap();
    assert_eq!(
        c.sha256,
        amcrax_engine::thermo::peng_robinson::CriticalProperties::embedded().sha256
    );
}
